// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        Attacker attacker = new Attacker();
        attacker.setTarget(address(c));

        vm.deal(address(attacker), amount);
        attacker.deposit{value: amount}();

        bool ok;
        try attacker.attack() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: single withdrawAll always succeeds (re-entry is a no-op
        // because credit is cleared before the external call), leaving the
        // contract's ether fully paid out. Mutant: re-entry withdraws a second
        // time, the balance underflows and the whole call reverts.
        assertTrue(ok && address(c).balance == 0);
    }
}

contract Attacker {
    C c;
    bool reentered;

    function setTarget(address t) external { c = C(t); }

    function deposit() external payable { c.deposit{value: msg.value}(); }

    function attack() external {
        reentered = false;
        c.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}

