pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        Reverter actor = new Reverter();
        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        c.deposit{value: amount}();

        vm.prank(address(actor));
        try c.withdrawAll() { /* should not succeed for a reverting recipient in P */ } catch { }

        // General rule: after any admissible withdrawAll attempt by a depositor,
        // the depositor's credit is preserved unless the external transfer actually succeeded.
        // P reverts on the failed transfer, so credit stays == amount; M zeroes it.
        assertTrue(c.credit(address(actor)) == amount);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < address(this).balance + 1 ether);
        Rejector r = new Rejector();
        vm.deal(address(r), amount);
        uint256 before = address(c).balance;
        vm.prank(address(r));
        c.deposit{value: amount}();
        assertEq(address(c).balance, before + amount);
        vm.prank(address(r));
        c.withdrawAll();
        // Rule: a withdrawal whose ETH transfer fails must not change the contract's balance.
        assertTrue(address(c).balance == before + amount);
    }
}

contract Rejector {
    receive() external payable { revert(); }
    function deposit(address c) external payable { C(c).deposit{value: msg.value}(); }
}

