pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdrawAll();

        // After a full deposit/withdraw cycle, the internal accounting balance
        // must be zero: balance tracks deposits minus withdrawals.
        assertTrue(c.balance() == 0, "balance must drop on withdrawal");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0); // plain recipient so the withdrawal call succeeds
        amount = bound(amount, 1, type(uint256).max / 2);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdrawAll();

        // General rule: after a full deposit/withdraw cycle the contract holds no Ether
        // (internal balance tracks withdrawals exactly). The mutant drops the balance
        // decrement, so its internal accounting no longer tracks withdrawals.
        assertTrue(address(c).balance == 0, "balance must drop to zero after withdrawal");
    }
}
